170:   function advanceTurn(){
171:     if(state.winner!==null)return;
172:     state.current=(state.current+1)%colors.length;
173:     if(state.current===0)state.round++;
174:     state.phase='roll';state.legal=[];state.dice=null;state.lastCapture=null;busy=false;
175:     state.message=state.current===0?'Bring a rogue out of hiding with a six.':`${colors[state.current].name} is sizing up the yard.`;
176:     render();
177:     if(state.current!==0)schedule(roll,650);
178:   }
179:   function moveToken(ci,ti){
180:     if(busy||state.phase!=='choose'||ci!==state.current||!state.legal.includes(ti))return;
181:     const token=state.tokens[ci][ti];
182:     busy=true;state.phase='busy';render();
183:     const moveBy=token.step<0?0:state.dice;
184:     schedule(()=>{
185:       const old=token.step;
186:       if(old<0)token.step=0;else token.step+=moveBy;
