193:       else if(token.step===57){state.message=`Home safe! Rogue ${ti+1} made it to the oak tree.`;state.event='One rascal slipped past the neighbors and made it home.';}
194:       else if(old<0){state.message='Out of the hideout! Now cross the backyard.';state.event='A new rogue is loose in the garden.';}
195:       else {state.message=`Nice and quiet. Rogue ${ti+1} moved ${state.dice} spaces.`;state.event='Not a squeak from the neighbors.';}
196:       busy=false;
197:       if(state.tokens[ci].every(t=>t.step>=57)){state.winner=ci;state.phase='over';state.message=`${colors[ci].name} got all four home. The yard is yours!`;state.event='All four rogues made it home. A clean getaway!';notify(`${colors[ci].name} wins the backyard!`);}
198:       else if(state.dice===6){state.phase='extra';state.legal=[];state.message='Six! You earned another roll.';}
199:       else {state.phase='roll';state.legal=[];}
200:       render();
201:       if(captured){schedule(()=>{state.lastCapture=null;render();},1400);}
202:       if(state.winner===null&&state.dice!==6)schedule(advanceTurn,650);
203:       else if(state.winner===null&&ci!==0)schedule(roll,650);
204:     },ci===0?230:380);
205:   }
206:   function aiChoose(){
207:     if(state.current===0||state.phase!=='choose'||state.winner!==null)return;
208:     const ci=state.current, options=state.legal.slice();
209:     const scored=options.map(ti=>{
210:       const token=state.tokens[ci][ti];let score=0;
211:       if(token.step<0)score+=5;
212:       else if(token.step+state.dice>=57)score+=20;
213:       else if(token.step>=51)score+=5;
214:       const next=token.step<0?0:token.step+state.dice;
215:       if(next<52){const p=(colors[ci].start+next)%52;if(!safeIndexes.has(p)&&colors.some((_,oi)=>oi!==ci&&state.tokens[oi].some(t=>globalPos(oi,state.tokens[oi].indexOf(t))===p)))score+=11;}
216:       return {ti,score};
217:     }).sort((a,b)=>b.score-a.score);
218:     moveToken(ci,scored[0].ti);
219:   }
